technical-specifications.spec:

def standardize(self, df: pl.DataFrame) -> pl.DataFrame:
    column_map = {"time": "timestamp", "o": "open", "h": "high", "l": "low", "c": "close", "v": "volume"}
    df = df.rename(column_map)
    df = df.with_columns([
        pl.col("timestamp").cast(pl.Datetime("us")).dt.replace_time_zone("UTC"),
    ])
    for col in ["open", "high", "low", "close", "volume"]:
        df = df.with_columns([pl.col(col).cast(pl.Decimal(precision=18, scale=8))])
    return df


async def get_funding_rates(self, symbol: str) -> pl.DataFrame:
    response = await self._client.get("/funding-rates", params={"symbol": symbol})
    return pl.DataFrame([
        {"timestamp": rate["timestamp"], "symbol": symbol, "funding_rate": Decimal(str(rate["rate"]))}
        for rate in response.json().get("rates", [])
    ])
